import React from 'react';
import { useLocation } from 'react-router-dom';

const ConfirmedScreen = () => {
  const location = useLocation();
  const { course, student } = location.state || {};

  const handleJoinWhatsApp = () => {
    // Replace with your actual WhatsApp group invite link
    const whatsappLink = "https://chat.whatsapp.com/YOUR_GROUP_INVITE_CODE";
    window.open(whatsappLink, '_blank', 'noopener,noreferrer');
  };

  return (
    <div className="p-8 max-w-md mx-auto mt-10 border rounded-lg shadow-md bg-white text-center">
      <div className="text-green-500 text-5xl mb-4">✅</div>
      <h2 className="text-3xl font-bold mb-2">Registration Confirmed!</h2>
      <p className="text-gray-600 mb-6">
        Thank you, {student?.name || 'Student'}! Your enrollment for <strong>{course?.title || 'the course'}</strong> is successful.
      </p>

      <div className="bg-blue-50 p-4 rounded mb-6 border border-blue-100">
        <p className="text-sm text-blue-800 mb-3">
          Please join our official WhatsApp group to get course updates, schedules, and materials.
        </p>
        <button 
          onClick={handleJoinWhatsApp}
          className="w-full bg-green-500 text-white py-3 rounded font-bold hover:bg-green-600 flex items-center justify-center gap-2"
        >
          Join WhatsApp Group
        </button>
      </div>
    </div>
  );
};

export default ConfirmedScreen;
